/* Game structures. Started from re/ghidra/types.h (re/tools/gen_structs_h.py), now maintained by hand.
 * Offsets in comments refer to the DOS layout; keep re/ghidra/types.h in sync when renaming. */
#ifndef SH_STRUCTS_H
#define SH_STRUCTS_H

/* ---- game structs (auto-generated by re/tools/genstruct.py, refine by hand) ---- */
typedef struct ORBIT { int x; int y; unsigned char angle; unsigned char pad[3]; } ORBIT;
typedef struct BGOBJ { int x; int y; int sprite; int w; int h; int hw; int hh; unsigned char layer; unsigned char active; unsigned char pad_1e[2]; } BGOBJ;
typedef struct STAR { int x; int y; unsigned char speed; unsigned char color; unsigned char alive; unsigned char pad_0b; } STAR;
typedef struct SHIPTYPE {         /* 0x30 bytes, 3 at 0xc886c */
   int sprite;                   /* SPACEHOG.DAT index */
   int flame_x, flame_y;         /* engine flame offset */
   int gun_x, gun_y;             /* muzzle offset */
   unsigned char lvl[9];         /* starting weapon levels */
   unsigned char maxlvl[9];      /* maximum weapon levels */
   unsigned char addon_max[9];   /* maximum levels reachable with ADD-ON */
   unsigned char pad_2f;
} SHIPTYPE;
/* PLAYER.control */
enum { CTRL_KEYBOARD = 0, CTRL_PAD = 1, CTRL_MOUSE = 2 };

typedef struct PLAYER {           /* 0xe4 bytes, 2 at 0xae088 */
   unsigned char control;        /* 0x00 0 keyboard, 1 gamepad, 2 mouse */
   unsigned char pad_01[3];
   int x, y;                     /* 0x04 position (ship centre) */
   int vx, vy;                   /* 0x0c velocity, clamped to +-speed */
   unsigned char lives;          /* 0x14 */
   unsigned char fire_delay;     /* 0x15 ticks between shots */
   unsigned char fire_wait;      /* 0x16 countdown until the next shot (0 = ready) */
   unsigned char bar_dirty;      /* 0x17 status bar must be redrawn */
   unsigned char flame;          /* 0x18 engine flame animation frame 1..3 */
   unsigned char pad_19[3];
   int muzzle;                   /* 0x1c draw muzzle flash this frame */
   int invuln;                   /* 0x20 invulnerability after (re)spawn, ticks */
   int warp_in;                  /* 0x24 warp-in animation; no control while > 0 */
   int dead;                     /* 0x28 out of lives */
   int powerup;                  /* 0x2c highlighted power-up lamp (-1 none), SELECT buys it */
   union {                       /* 0x30 weapon levels */
      struct { unsigned char speed, gun, side, buildup, missile, plasma, magma, option, addon; };
      unsigned char wlvl[9];
   };
   unsigned char pad_39[3];
   int score;                    /* 0x3c */
   int sprite;                   /* 0x40 SPACEHOG.DAT index of the ship sprite */
   int hw, hh;                   /* 0x44 half sprite size */
   int w, h;                     /* 0x4c sprite size */
   int start_x, start_y;         /* 0x54 (re)spawn position */
   int charge_tick;              /* 0x5c buildup charge accumulator */
   int charge;                   /* 0x60 buildup charge */
   int charge_max;               /* 0x64 */
   int blast;                    /* 0x68 buildup blast radius while it expands */
   int specials;                 /* 0x6c special weapon charges */
   int special_time;             /* 0x70 special weapon active, ticks */
   int saved_plasma;             /* 0x74 plasma level to restore after Berserk */
   int select_held;              /* 0x78 SELECT latch */
   unsigned char lock;           /* 0x7c weapons locked: no downgrade on death */
   unsigned char missiles;       /* 0x7d missiles in flight */
   unsigned char pad_7e[2];
   ORBIT orbit[4];               /* 0x80 orbiting options */
   SHIPTYPE ship;                /* 0xb0 copy of the ship type */
   int shipno;                   /* 0xe0 ship type index */
} PLAYER;
typedef struct ENEMY {            /* 0x94 bytes, 50 at 0xae6c8; 40 templates at 0xc8fd0 */
   int x, y;                     /* 0x00 centre */
   int vx, vy;                   /* 0x08 (path enemies: previous position) */
   int path_pos;                 /* 0x10 index into the wave path, -1 = free movement */
   int wave;                     /* 0x14 g_wave index of path enemies */
   int move;                     /* 0x18 movement: 2 orbit parent, 3 stop and go, 4 dodge, 6 own path */
   unsigned char hit_flash;      /* 0x1c hit this frame: drawn white */
   unsigned char targeted;       /* 0x1d a homing missile has picked it */
   unsigned char drop;           /* 0x1e bonus dropped on death (1..9), 'c' = boss */
   unsigned char pad_1f[1];
   int hp;                       /* 0x20 */
   int sprite;                   /* 0x24 SPACEHOG.DAT index of the first frame */
   int anim;                     /* 0x28 g_anim[] speed class for the frame */
   int expl_size;                /* 0x2c explosion size on death */
   unsigned char active;         /* 0x30 */
   unsigned char pad_31[3];
   int points;                   /* 0x34 score for a kill */
   int hw, hh;                   /* 0x38 half size */
   int w, h;                     /* 0x40 size */
   int gun_x, gun_y;             /* 0x48 bullet spawn offset */
   int fire_rate;                /* 0x50 ticks between shots (0 = never) */
   int fire_count;               /* 0x54 */
   int bullet;                   /* 0x58 g_ebullet_tmpl index */
   unsigned char immune;         /* 0x5c weapon classes that bounce off; 0x40 = no homing */
   unsigned char masked;         /* 0x5d sprite is a BITMAP: masked draw + pixel collision */
   unsigned char angle;          /* 0x5e orbit angle */
   unsigned char pad_5f[1];
   int spin;                     /* 0x60 orbit speed (stop and go: saved vx) */
   int radius;                   /* 0x64 orbit radius shift (stop and go: stop x) */
   unsigned char parent;         /* 0x68 enemy it is attached to, 0xff = none */
   unsigned char pad_69[3];
   int rel_x, rel_y;             /* 0x6c offset to the parent (stop and go: rel_y = stop time) */
   unsigned char invulnerable;   /* 0x74 shots pass through */
   unsigned char debris;         /* 0x75 extra explosions on death */
   unsigned char pad_76[2];
   int *path;                    /* 0x78 own path (move 6) */
   unsigned char tmpl;           /* 0x7c template index */
   char name[23];                /* 0x7d shown by the enemy info cheat */
} ENEMY;
/* SHOT.kind (also the bits of ENEMY.immune) */
enum { SHOT_GUN = 1, SHOT_SIDE = 2, SHOT_MAGMA = 8, SHOT_MISSILE = 0x20, NO_HOMING = 0x40 };

typedef struct SHOT { /* 0x44 bytes, 200 at 0xa5f0c */
   int x;
   int y;
   int vx;
   int vy;
   int vmax;
   unsigned char pad_14[4];
   unsigned char damage;
   unsigned char pad_19[3];
   int sprite;
   unsigned char active;
   unsigned char owner;
   unsigned char pad_22[2];
   int hw;
   int hh;
   int w;
   int h;
   int bounced;
   unsigned char kind;
   unsigned char pad_39[3];
   int target;
   unsigned char dir;
   unsigned char pad_41[3];
} SHOT;
typedef struct PICKUP { /* 0x2c bytes, 10 at 0xae340 */
   int x;
   int y;
   int sprite;
   int frame;
   int f_10;
   int type;
   unsigned char active;
   unsigned char pad_19[3];
   int hw;
   int hh;
   int w;
   int h;
} PICKUP;
typedef struct EXPLOSION { /* 0x20 bytes, 50 at 0xc8954 */
   int x;
   int y;
   int vx;
   int vy;
   unsigned char frame;
   unsigned char active;
   unsigned char size;
   unsigned char frames;
   unsigned char kind;
   unsigned char pad_15[3];
   int hw;
   int hh;
} EXPLOSION;
typedef struct EBULLET {            /* 0x48 bytes: enemy bullets (100 at 0xcac34, 5 templates at 0xc8598) */
   int aim;                      /* 0x00 0 random direction, 5 aimed at a player, else straight */
   int x, y;                     /* 0x04 centre */
   int vx, vy;                   /* 0x0c */
   int sprite;                   /* 0x14 SPACEHOG.DAT index of the first frame */
   int anim;                     /* 0x18 g_anim[] speed class */
   unsigned char active;         /* 0x1c */
   unsigned char pad_1d[3];
   int hw, hh;                   /* 0x20 half size */
   int w, h;                     /* 0x28 size */
   unsigned char pad_30[4];
   char name[20];                /* 0x34 template name (enemy info cheat) */
} EBULLET;
typedef struct PARTICLE { /* 0x1c bytes, 100 at 0xa5348 */
   int x;
   int y;
   int vx;
   int vy;
   int color;
   int active;
   int age;
} PARTICLE;
typedef struct LEVELEVENT { /* 0x40 bytes, 256 at 0xaa088: level events (from the .lev file) */
   int time;                 /* 0x00 level step at which the event fires */
   unsigned char kind;       /* 0x04 0/3/4/6 enemy, 1 wave, 2 orbiting enemy, 5 bg object, 9 end */
   unsigned char tmpl;       /* 0x05 enemy template / background sprite */
   unsigned char pad_06[2];
   int y;                    /* 0x08 */
   int x;                    /* 0x0c */
   int vx;                   /* 0x10 (wave: path step) */
   int vy;                   /* 0x14 (bg object: layer) */
   int path;                 /* 0x18 shlev pattern index */
   int count;                /* 0x1c wave enemy count */
   int interval;             /* 0x20 wave spawn interval */
   int p24;                  /* 0x24 kind 3: stop x; kind 2: radius shift */
   int p28;                  /* 0x28 kind 2: start angle */
   int p2c;                  /* 0x2c kind 2: angular speed */
   int relx;                 /* 0x30 offset from parent */
   int rely;                 /* 0x34 */
   int attach;               /* 0x38 -2: attach to parent, 0: becomes parent */
   unsigned char flags;      /* 0x3c enemy drop type, 'c' = boss */
   unsigned char pad_3d[3];
} LEVELEVENT;
typedef struct OBJ28 { /* 0x28 bytes, 10 at 0xccc80 */
   unsigned char pad_00[1];
   unsigned char f_01;
   unsigned char f_02;
   unsigned char f_03;
   unsigned char f_04;
   unsigned char f_05;
   unsigned char f_06;
   unsigned char f_07;
   int f_08;
   unsigned char f_0c;
   unsigned char f_0d;
   unsigned char pad_0e[2];
   int f_10;
   int f_14;
   unsigned char pad_18[16];
} OBJ28;

typedef struct HISCORE { char name[20]; int score; int ship; } HISCORE;

typedef struct WAVE { /* 0x28 bytes, 10 at 0xccc68 */
   unsigned char idx[25];
   unsigned char alive;      /* 0x19 */
   unsigned char tmpl;       /* 0x1a */
   unsigned char remaining;  /* 0x1b */
   unsigned char interval;   /* 0x1c */
   unsigned char yofs;       /* 0x1d */
   unsigned char timer;      /* 0x1e */
   unsigned char step;       /* 0x1f */
   int *path;                /* 0x20 */
   unsigned char bonus;      /* 0x24 drop a power-up when the whole wave is shot */
   unsigned char active;     /* 0x25 */
   unsigned char pad_26[2];
} WAVE;
typedef struct LEVELHDR { char name[80]; int last_event; } LEVELHDR;

#endif
